package dev.codex.lastzhelper;
import android.app.*;import android.content.*;import android.graphics.PixelFormat;import android.os.*;import android.provider.Settings;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import java.util.*;import org.json.*;
public final class HelperService extends Service implements JobRunner.Listener {
 WindowManager wm;View overlay;WindowManager.LayoutParams lp;boolean expanded=false;
 RunAwake diagnosticAwake;
 TextView handle,info;EditText from,to,skipState,powerLimit;CheckBox dry;RadioGroup destination;final List<View> controls=new ArrayList<>();
 int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 public void onCreate(){super.onCreate();wm=(WindowManager)getSystemService(WINDOW_SERVICE);NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("lastz-control","Last Z runs",NotificationManager.IMPORTANCE_LOW));startForeground(40,notification());JobRunner.listeners.add(this);JobRunner.recover(this);}
 Notification notification(){PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT),stop=PendingIntent.getService(this,1,new Intent(this,HelperService.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,"lastz-control").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("Last Z Helper: "+JobRunner.state).setContentText(JobRunner.summary).setContentIntent(open).addAction(new Notification.Action.Builder(null,"Stop",stop).build()).setOngoing(true).build();}
 public int onStartCommand(Intent i,int flags,int id){String action=i==null?null:i.getAction();if(i==null){JobRunner.resume(this);if(JobRunner.busy&&Settings.canDrawOverlays(this)){expanded=false;show();}return JobRunner.busy?START_STICKY:START_NOT_STICKY;}if("bubble".equals(action)){if(Settings.canDrawOverlays(this)){expanded=true;show();}}else if("stop".equals(action))JobRunner.stop(this);else if("hide".equals(action))hide();else if("hold-awake".equals(action)){RunAwake next=new RunAwake(this,10*60*1000L);if(diagnosticAwake!=null)diagnosticAwake.close();diagnosticAwake=next;}else if("release-awake".equals(action)){if(diagnosticAwake!=null)diagnosticAwake.close();diagnosticAwake=null;}else if(action!=null){try{JSONObject o=i.hasExtra("options")?new JSONObject(i.getStringExtra("options")):JobRunner.options(this);expanded=false;if(Settings.canDrawOverlays(this))show();JobRunner.start(this,action,o);}catch(Exception e){JobRunner.publish("Error",e.toString());}}return JobRunner.busy?START_STICKY:START_NOT_STICKY;}
 public IBinder onBind(Intent i){return null;}
 void hide(){if(overlay!=null){((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(overlay.getWindowToken(),0);wm.removeView(overlay);overlay=null;}controls.clear();}
 void label(LinearLayout box,String text){TextView t=new TextView(this);t.setText(text);t.setTextColor(0xffffffff);t.setTextSize(13);box.addView(t);}
 EditText field(LinearLayout box,String label,int value){label(box,label);EditText e=new EditText(this);e.setSingleLine(true);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);e.setTextColor(0xffffffff);e.setTextSize(15);e.setText(String.valueOf(value));box.addView(e);controls.add(e);return e;}
 Button button(LinearLayout box,String text,Runnable click,boolean run){Button b=new Button(this);b.setText(text);b.setTextSize(12);box.addView(b);b.setOnClickListener(v->click.run());if(run)controls.add(b);return b;}
 boolean save(){if(!expanded||from==null)return true;try{int power=TruckRules.parsePowerLimit(powerLimit.getText().toString());int skipped=TruckRules.parseSkipState(skipState.getText().toString());int first=Integer.parseInt(from.getText().toString()),last=Integer.parseInt(to.getText().toString());if(first<1||last<first||last>9999||last-first>100)throw new IllegalArgumentException();getSharedPreferences("runs",0).edit().putInt("start",first).putInt("end",last).putInt("skipTruckState",skipped).putInt("attackPowerM",power).putBoolean("dry",dry.isChecked()).putString("shareDestination",SharingControls.selected(destination)).apply();return true;}catch(Exception e){Toast.makeText(this,"Check states, skip state and power limit.",Toast.LENGTH_LONG).show();return false;}}
 void launch(String mode){if(JobRunner.busy||!save())return;try{JSONObject options=JobRunner.options(this);if(mode.equals("resume-bounties")){mode="bounties";options.put("resume",true);}expanded=false;show();JobRunner.start(this,mode,options);}catch(Exception e){JobRunner.publish("Error",e.toString());}}
 void launchBot(boolean preview){if(JobRunner.busy)return;try{BotRun.service(this,preview);}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
 void show(){int x=lp==null?8:lp.x,y=lp==null?60:lp.y;hide();LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(8,6,8,6);box.setBackgroundColor(0xf020332f);handle=new TextView(this);handle.setTextColor(0xffffffff);handle.setTextSize(14);handle.setPadding(6,10,6,10);box.addView(handle);
  if(expanded){ScrollView scroll=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);int maxHeight=Math.max(dp(180),getResources().getDisplayMetrics().heightPixels-dp(190));box.addView(scroll,new LinearLayout.LayoutParams(-1,maxHeight));info=new TextView(this);info.setTextColor(0xffffffff);info.setTextSize(12);info.setMaxLines(5);body.addView(info);
   android.content.SharedPreferences p=getSharedPreferences("runs",0);label(body,"Share destination");destination=SharingControls.create(this,p.getString("shareDestination",ShareDestination.WORLD),true);body.addView(destination);
   button(body,"Share 2+ orange frags",()->launch("truck-share-2"),true);button(body,"Share 3+ orange frags",()->launch("truck-share-3"),true);button(body,"Share cargo combos",()->launch("truck-share-cargo"),true);button(body,"Attack 3+ on Gaarix",()->launch("truck-attack"),true);
   label(body,"Cargo: 4 boxes / 1 frag + 3 boxes / 2 frags + 2 boxes / 3+ frags. One chest icon = one box. Group trucks use the power limit; World trucks allow any known power.");
   dry=new CheckBox(this);dry.setText("Preview only - no messages or attacks");dry.setTextColor(0xffffffff);dry.setChecked(p.getBoolean("dry",true));body.addView(dry);controls.add(dry);
   powerLimit=field(body,"Power below (million) - Send / Attack",p.getInt("attackPowerM",440));skipState=field(body,"Skip state for World shares (0 = none)",p.getInt("skipTruckState",0));
   label(body,"Bounties");from=field(body,"Start state",p.getInt("start",17));to=field(body,"End state",p.getInt("end",64));button(body,"Share bounties",()->launch("bounties-share"),true);label(body,"Maintenance");button(body,"Run bot",()->launchBot(false),true);button(body,"Preview bot",()->launchBot(true),true);button(body,"Accounts and features",()->{if(save()){hide();startActivity(new Intent(this,RotationActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}},true);button(body,"Hide controls",()->{if(save())hide();},false);
  }else{info=null;from=to=skipState=powerLimit=null;dry=null;destination=null;}
  button(box,"STOP",()->JobRunner.stop(this),false);
  int width=expanded?Math.min(dp(340),getResources().getDisplayMetrics().widthPixels-dp(16)):dp(160);
  lp=new WindowManager.LayoutParams(width,WindowManager.LayoutParams.WRAP_CONTENT,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,expanded?WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL:WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.LEFT;lp.x=Math.max(0,Math.min(x,getResources().getDisplayMetrics().widthPixels-width));lp.y=expanded?Math.min(y,24):y;lp.softInputMode=WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING;overlay=box;
  handle.setOnTouchListener(new View.OnTouchListener(){float sx,sy;int ox,oy;boolean moved;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==0){sx=e.getRawX();sy=e.getRawY();ox=lp.x;oy=lp.y;moved=false;return true;}if(e.getAction()==2){float dx=e.getRawX()-sx,dy=e.getRawY()-sy;if(Math.abs(dx)+Math.abs(dy)>10)moved=true;lp.x=Math.max(0,Math.min(getResources().getDisplayMetrics().widthPixels-lp.width,ox+(int)dx));lp.y=Math.max(0,Math.min(getResources().getDisplayMetrics().heightPixels-100,oy+(int)dy));if(overlay!=null)wm.updateViewLayout(overlay,lp);return true;}if(e.getAction()==1){if(!moved&&(!expanded||save())){expanded=!expanded;show();}return true;}return false;}});wm.addView(box,lp);refresh();
 }
 void refresh(){if(overlay==null)return;handle.setText("Z - "+JobRunner.state+"  (tap / drag)");if(info!=null)info.setText(JobRunner.summary);for(View v:controls)v.setEnabled(!JobRunner.busy);SharingControls.enabled(destination,!JobRunner.busy);int flags=expanded&&!JobRunner.busy?WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL:WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE;if(lp.flags!=flags){lp.flags=flags;wm.updateViewLayout(overlay,lp);}}
 public void update(String s,String detail,boolean busy){((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(40,notification());refresh();}
 public void onDestroy(){if(diagnosticAwake!=null)diagnosticAwake.close();JobRunner.stop(this);hide();JobRunner.listeners.remove(this);super.onDestroy();}
}
